(() => {
  const API = '/api';
  const titles = {conversations:'對話',recall:'回想',changes:'變更紀錄',commitments:'承諾','demo-chat':'Demo Chat',capture:'Live Capture',privacy:'隱私'};
  const state = {conversations:[], activeId:localStorage.getItem('recall-active'), status:null};
  let route='conversations', sourceFocus=null, previewId=null, pendingConfirm=null, profilerTimer=null;
  const el=id=>document.getElementById(id);
  const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const fmt=iso=>iso?new Intl.DateTimeFormat('zh-TW',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Taipei'}).format(new Date(iso)):'—';
  const day=iso=>iso?new Intl.DateTimeFormat('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Taipei'}).format(new Date(iso)):'—';
  const api=async(path,options={})=>{const response=await fetch(API+path,{headers:{'Content-Type':'application/json'},...options});if(!response.ok){let detail='request_failed';try{detail=(await response.json()).detail}catch{}throw new Error(detail)}return response.json()};
  const active=()=>state.conversations.find(c=>c.id===state.activeId)||state.conversations[0];
  const categoryLabel=c=>({'food.spiciness':'飲食偏好 · 辣度','availability.next_week':'行程 · 可用時間','plan.birthday':'計畫 · 生日旅行','event.anniversary':'事件 · 週年紀念'})[c]||c;
  function toast(text){const t=el('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
  function loading(){el('view').innerHTML='<div class="empty"><span class="empty-icon">···</span><h3>正在讀取本機資料</h3></div>'}
  function empty(){return `<div class="empty"><span class="empty-icon">＋</span><h3>先建立一段對話</h3><p>回到對話頁載入合成資料或匯入 LINE TXT。</p><button class="btn primary" data-route="conversations">前往對話</button></div>`}

  async function refreshBase(){
    [state.conversations,state.status]=await Promise.all([api('/conversations'),api('/system/status')]);
    if(!active()&&state.conversations.length)state.activeId=state.conversations[0].id;
    if(state.activeId)localStorage.setItem('recall-active',state.activeId);
    const p=state.status.provider;document.querySelector('.provider-pill').innerHTML=`<span></span> ${esc(p.provider)} · ${p.status==='ready'?'Offline-ready':p.status}`;
  }
  async function routeTo(next){if(profilerTimer){clearInterval(profilerTimer);profilerTimer=null}route=next;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.route===route));el('page-title').textContent=titles[route];loading();try{await render();if(route==='capture')profilerTimer=setInterval(async()=>{if(route==='capture'){try{el('view').innerHTML=await renderCapture();bindView()}catch{}}},2000)}catch(error){el('view').innerHTML=`<div class="empty"><span class="empty-icon">!</span><h3>無法載入</h3><p>${esc(error.message)}。請確認本機 FastAPI 服務仍在執行。</p></div>`}}
  async function render(){
    const map={conversations:renderConversations,recall:renderRecall,changes:renderChanges,commitments:renderCommitments,'demo-chat':renderChat,capture:renderCapture,privacy:renderPrivacy};
    el('view').innerHTML=await map[route]();bindView();requestAnimationFrame(focusSource);
  }

  async function renderConversations(){
    await refreshBase();const total=state.status.message_count;
    const cards=state.conversations.map(c=>`<article class="conversation-card" data-open="${c.id}"><div class="conv-title"><span class="avatar">${esc(c.title[0])}</span><div><strong>${esc(c.title)}</strong><small>${({line_txt:'LINE 匯入',live_capture:'Live Capture',synthetic_demo:'合成示範資料'})[c.source_type]||esc(c.source_type)} · ${esc(c.timezone)}</small></div></div><div class="meta"><small>參與者</small><strong>${c.participant_count} 人</strong></div><div class="meta"><small>訊息</small><strong>${c.message_count.toLocaleString()}</strong></div><div class="meta"><small>日期範圍</small><strong>${day(c.date_start)} — ${day(c.date_end)}</strong></div><span class="status">● ${c.memory_status==='complete'?'索引完成':'處理中'}</span><button type="button" class="btn ghost" data-delete-conversation="${c.id}">刪除</button></article>`).join('');
    return `<div class="hero-row"><div><h2>你的本機對話記憶</h2><p>原始訊息、FTS 索引與時間記憶都保存在本機 SQLite。</p></div><div class="actions"><button class="btn secondary" id="load-sample">＋ 載入 5,000 筆範例</button><button class="btn primary" id="open-import">↥ 匯入 LINE TXT</button></div></div><div class="stats-grid"><div class="stat-card"><small>本機對話</small><strong>${state.status.conversation_count}</strong></div><div class="stat-card"><small>已索引訊息</small><strong>${total.toLocaleString()}</strong></div><div class="stat-card"><small>推論提供者</small><strong style="font-size:14px">${esc(state.status.provider.provider)}</strong></div><div class="stat-card"><small>上次索引</small><strong style="font-size:15px">${fmt(state.status.last_indexed)}</strong></div></div>${cards||`<div class="empty"><span class="empty-icon">⌕</span><h3>還沒有對話</h3><p>載入完全合成的資料即可走過提問、引用、時間變更與拒答流程。</p><button class="btn primary" id="empty-sample">載入示範資料</button></div>`}`;
  }
  async function renderRecall(){const c=active();if(!c)return empty();const memories=await api(`/conversations/${c.id}/memories`);const current=memories.filter(x=>x.status==='current').sort((a,b)=>b.valid_from.localeCompare(a.valid_from));return `<div class="hero-row"><div><h2>問你的聊天紀錄</h2><p>答案只使用 SQLite 中的原始訊息；每個事實都需通過引用驗證。</p></div></div><div class="recall-layout"><div class="panel"><label class="eyebrow">SELECTED CONVERSATION</label><select id="conversation-select" class="select">${state.conversations.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.title)} · ${x.message_count.toLocaleString()} 則</option>`).join('')}</select><div class="query-composer"><input id="query" class="query-box" placeholder="例如：Alice 現在可以吃辣嗎？" autocomplete="off"><button id="ask" class="btn primary">尋找答案</button></div><div class="suggestions"><button data-question="Alice 現在可以吃辣嗎？">現在可以吃辣嗎？</button><button data-question="生日旅行最後決定去哪裡？">生日旅行去哪？</button><button data-question="下週哪天沒空？">哪天沒空？</button><button data-question="Alice 的貓叫什麼名字？">問一題不存在的</button></div><div id="answer"></div></div><aside class="panel"><h3>目前記得的事</h3><div class="memory-list">${current.slice(0,8).map(m=>`<div class="memory-mini"><strong>${categoryLabel(m.category)}</strong><span>${esc(m.display_value)} · ${Math.round(m.confidence*100)}%</span></div>`).join('')||'<p class="context-card">目前沒有抽取出的記憶。</p>'}</div></aside></div>`}
  function answerHTML(r){const label={supported:'● SUPPORTED',ambiguous:'△ AMBIGUOUS',not_found:'○ NOT FOUND'}[r.status];return `<article class="answer-card"><span class="result-status">${label}</span><h2>${esc(r.answer)}</h2><p>${esc(r.explanation)}</p>${r.citations.map(c=>`<div class="citation" data-source="${c.message_id}"><small>${esc(c.speaker)} · ${fmt(c.timestamp)} · ${esc(c.message_id)}</small><blockquote>「${esc(c.quote)}」</blockquote><small>開啟原始訊息與上下文 ↗</small></div>`).join('')}</article>`}
  async function runQuestion(){const q=el('query').value.trim();if(!q)return toast('請先輸入問題');el('ask').disabled=true;el('answer').innerHTML='<p class="context-card">正在檢索記憶與原始訊息…</p>';try{const result=await api(`/conversations/${active().id}/query`,{method:'POST',body:JSON.stringify({question:q})});el('answer').innerHTML=answerHTML(result);el('answer').querySelectorAll('[data-source]').forEach(x=>x.onclick=()=>{sourceFocus=x.dataset.source;routeTo('demo-chat')})}catch(e){toast(e.message)}finally{el('ask').disabled=false}}

  async function renderChanges(){const c=active();if(!c)return empty();const groups=await api(`/conversations/${c.id}/changes`);return `<div class="hero-row"><div><h2>事實不是靜止的</h2><p>較新的明確敘述只會取代同一個人、同一類別的舊狀態。</p></div></div>${groups.map(g=>`<div class="panel" style="margin-bottom:14px"><h3>${esc(g.subject)} · ${categoryLabel(g.category)}</h3><div class="timeline">${[...g.history].sort((a,b)=>b.valid_from.localeCompare(a.valid_from)).map(m=>`<article class="timeline-item ${m.status==='current'?'current':''}"><header><div><small>${fmt(m.valid_from)}</small><h4>${esc(m.display_value)}</h4></div><span class="tag ${m.status==='current'?'current':''}">${m.status==='current'?'目前狀態':m.status==='uncertain'?'不確定':'已被取代'}</span></header><p>信心 ${Math.round(m.confidence*100)}% · <button class="btn ghost" data-source="${m.source_message_ids[0]}" style="padding:5px 8px;margin-top:8px">查看來源</button></p></article>`).join('')}</div></div>`).join('')||`<div class="empty"><span class="empty-icon">↝</span><h3>還沒有明確變更</h3><p>明確的新狀態出現後，舊版本會保留在這裡。</p></div>`}`}
  async function renderCommitments(){const c=active();if(!c)return empty();const items=await api(`/conversations/${c.id}/commitments`);const labels={open:'待完成',done:'已完成',cancelled:'已取消',uncertain:'不確定'};return `<div class="hero-row"><div><h2>說過要做的事</h2><p>承諾及完成狀態都需有不同的原始訊息支持。</p></div></div><div class="panel" style="padding:0">${items.map(x=>`<article class="commitment"><span class="check-circle">${x.status==='done'?'✓':'○'}</span><div><h4>${esc(x.action)}</h4><p>${esc(x.who)} · ${x.due_date?'期限 '+(x.due_date==='next_sunday'?'下個星期日':x.due_date):'未指定期限'} · <button class="btn ghost" data-source="${x.source_message_id}" style="padding:4px 7px">來源</button>${x.completed_message_id?` · <button class="btn ghost" data-source="${x.completed_message_id}" style="padding:4px 7px">狀態來源</button>`:''}</p></div><span class="tag ${x.status==='open'?'open':'current'}">${labels[x.status]||'不確定'}</span></article>`).join('')||'<div class="empty"><span class="empty-icon">✓</span><h3>尚無承諾</h3><p>Demo Chat 中輸入「我答應星期日前訂好餐廳」即可建立一筆。</p></div>'}</div>`}

  async function renderChat(){const c=active();if(!c)return empty();const path=`/conversations/${c.id}/messages?limit=${sourceFocus?41:80}${sourceFocus?'&around='+encodeURIComponent(sourceFocus):''}`;const messages=await api(path);const label=sourceFocus?'來源訊息前後文':'最近 80 則';return `<div class="chat-wrap"><div class="panel chat-panel"><div class="chat-head"><div><strong>${esc(c.title)}</strong><small style="display:block;color:var(--muted);margin-top:4px">canonical messages · ${label}</small></div><span class="status">● API 即時索引</span></div><div class="chat-messages" id="chat-messages">${messages.map(m=>messageHTML(m)).join('')}</div><div class="composer"><select class="select" id="speaker"><option>Alice</option><option>小宇</option></select><input class="query-box" id="chat-input" placeholder="生日旅行確定改去宜蘭，我已經訂好民宿了"><button class="btn primary" id="send">送出</button></div></div><aside class="panel"><h3>正式 ingestion 路徑</h3><p class="context-card">這裡的訊息會寫入和 LINE 匯入相同的 messages table，建立 FTS5 索引，再重新執行記憶抽取與時序解析。</p><div class="callout"><strong>建議 demo</strong><br>新增「生日旅行確定改去宜蘭，我已經訂好民宿了」，再回到回想頁重問目的地。</div><div class="callout warning" style="margin-top:10px">模擬聊天不包含帳號、傳輸、自動回覆或第三方服務。</div></aside></div>`}
  function messageHTML(m){return `<div class="message ${m.sender==='小宇'?'me':''}" id="source-${m.id}"><span class="avatar" style="width:28px;height:28px;border-radius:9px;font-size:10px">${esc(m.sender[0])}</span><div class="bubble">${esc(m.content).replace(/\n/g,'<br>')}<small>${esc(m.sender)} · ${fmt(m.timestamp)}</small></div></div>`}
  async function sendMessage(){const input=el('chat-input'),content=input.value.trim();if(!content)return;el('send').disabled=true;try{const result=await api(`/conversations/${active().id}/messages`,{method:'POST',body:JSON.stringify({sender:el('speaker').value,content})});sourceFocus=result.message.id;await refreshBase();await render();toast('訊息、FTS 索引與時間記憶已更新')}catch(e){toast(e.message)}finally{if(el('send'))el('send').disabled=false}}
  function focusSource(){const box=el('chat-messages');if(!box)return;if(sourceFocus){const target=el(`source-${sourceFocus}`);if(target){target.classList.add('flash');target.scrollIntoView({block:'center'})}sourceFocus=null}else box.scrollTop=box.scrollHeight}

  async function renderPrivacy(){await refreshBase();const s=state.status,p=s.provider;return `<div class="hero-row"><div><h2>資料留在你的機器</h2><p>後端只綁定 127.0.0.1，沒有 analytics、遠端字型或雲端 fallback。</p></div></div><div class="privacy-grid"><article class="privacy-card"><h3>推論與網路</h3><div class="privacy-line"><span>推論提供者</span><strong>${esc(p.provider)}</strong></div><div class="privacy-line"><span>健康狀態</span><strong style="color:var(--green)">${esc(p.status)}</strong></div><div class="privacy-line"><span>本機限定</span><strong>${s.local_only?'是':'否'}</strong></div><div class="privacy-line"><span>UGen300 效能</span><strong>${esc(s.ugen300_benchmark)}</strong></div></article><article class="privacy-card"><h3>本機資料</h3><div class="privacy-line"><span>資料庫</span><strong title="${esc(s.database_path)}">SQLite</strong></div><div class="privacy-line"><span>對話數</span><strong>${s.conversation_count}</strong></div><div class="privacy-line"><span>訊息數</span><strong>${s.message_count.toLocaleString()}</strong></div><div class="privacy-line"><span>靜態加密</span><strong>${s.database_encrypted?'已啟用':'未實作'}</strong></div></article></div><div class="panel" style="margin-top:14px"><h3>離線驗證</h3><div class="callout">${esc(s.network_claim)} 關閉 Wi-Fi 後，重新提問、查看引用與新增 Demo Chat 訊息都應成功。</div><div class="actions" style="margin-top:16px"><button id="delete-active" class="btn secondary" ${active()?'':'disabled'}>刪除目前對話</button><button id="delete-all" class="btn danger" ${s.conversation_count?'':'disabled'}>刪除全部本機資料</button></div></div><div class="panel" style="margin-top:14px"><h3>Stage II 介面</h3><p class="context-card"><code>HailoInferenceProvider</code> 已被隔離在 inference provider 邊界，待 Linux + ASUS UGen300 USB 8GB 實機取得後接上 HailoRT。macOS 版本不宣稱原生 Hailo 支援。</p></div>`}

  async function renderCapture(){const p=await api('/system/profiler'),c=p.capture;const stateLabel={stopped:'已停止',starting:'正在啟動',selecting_window:'等待選擇視窗',capturing:'擷取中',paused:'已暫停',stopping:'正在停止',cancelled:'已取消',error:'發生錯誤'}[c.status]||c.status;return `<div class="hero-row"><div><h2>明確選取單一視窗</h2><p>使用 macOS 系統選擇器與 Apple Vision；只處理畫面上可見文字，不保存截圖。</p></div></div><div class="panel"><div class="privacy-line"><span>狀態</span><strong id="capture-state">${esc(stateLabel)}</strong></div><p class="context-card">開始後會出現系統視窗選擇器。OCR 信心不足的文字不會匯入；無法辨認的發言者與訊息時間會標為未知。</p><div class="actions"><button id="capture-start" class="btn primary" ${['capturing','paused','selecting_window','starting'].includes(c.status)?'disabled':''}>開始並選擇視窗</button><button id="capture-pause" class="btn secondary" ${c.status==='capturing'?'':'disabled'}>暫停</button><button id="capture-resume" class="btn secondary" ${c.status==='paused'?'':'disabled'}>繼續</button><button id="capture-stop" class="btn danger" ${['capturing','paused','selecting_window','starting'].includes(c.status)?'':'disabled'}>停止</button></div>${c.error?`<p class="callout warning">${esc(c.error)}。請確認 macOS 螢幕錄製權限已授予執行此程式的終端機或應用程式。</p>`:''}</div><div class="panel" style="margin-top:14px"><div class="hero-row"><div><h3>即時流程分析</h3><p>最近 ${p.window_seconds} 秒 · 不記錄聊天文字</p></div><div class="actions"><button id="profiler-pause" class="btn secondary">${p.sampling_paused?'恢復取樣':'暫停取樣'}</button><button id="profiler-reset" class="btn ghost">重設計數</button></div></div><div class="stats-grid"><div class="stat-card"><small>觀察畫格</small><strong>${c.frames_observed||0}</strong></div><div class="stat-card"><small>新訊息</small><strong>${p.counters.new_text_detected||0}</strong></div><div class="stat-card"><small>重複略過</small><strong>${p.counters.duplicates_dropped||0}</strong></div><div class="stat-card"><small>不確定文字</small><strong>${c.uncertain_detections||0}</strong></div></div><div class="privacy-grid">${Object.entries(p.timings).map(([name,t])=>`<article class="privacy-card"><h3>${esc(name)}</h3><div class="privacy-line"><span>樣本數</span><strong>${t.count}</strong></div><div class="privacy-line"><span>p50 / p95</span><strong>${t.p50_ms} / ${t.p95_ms} ms</strong></div></article>`).join('')||'<p class="context-card">尚無量測資料；開始擷取或新增 Demo Chat 訊息後會顯示處理時間。</p>'}</div><p class="context-card">主機 CPU 累計：${p.host.cpu_user_seconds}s user / ${p.host.cpu_system_seconds}s system · RSS：${p.host.resident_memory_mb} MB（峰值） · 加速器：Not available</p></div>`}

  async function updateCaptureBanner(){try{const p=await api('/system/profiler'),c=p.capture,banner=el('capture-banner');const activeCapture=['starting','selecting_window','capturing','paused','stopping'].includes(c.status);banner.hidden=!activeCapture;if(activeCapture){const target=[c.app_label,c.window_label].filter(Boolean).join(' · ')||'等待選擇視窗';el('capture-banner-label').textContent=c.status==='paused'?`Live Capture 已暫停：${target}`:`Live Capture 狀態 ${c.status}：${target}`;if(el('capture-banner-stop'))el('capture-banner-stop').disabled=c.status==='stopping'}}catch{}}

  function bindView(){
    if(el('delete-active')&&state.status){let detail=document.getElementById('privacy-path-details');if(!detail){detail=document.createElement('p');detail.id='privacy-path-details';detail.className='context-card';el('delete-active').closest('.panel').append(detail)}detail.textContent=`SQLite 路徑：${state.status.database_path} · 上次索引：${fmt(state.status.last_indexed)}`}
    if(el('capture-state'))api('/system/profiler').then(p=>{const grid=el('capture-state').closest('.panel').nextElementSibling?.querySelector('.stats-grid');if(!grid)return;let extra=document.getElementById('profiler-throughput');if(!extra){extra=document.createElement('p');extra.id='profiler-throughput';extra.className='context-card';grid.after(extra)}const provider=p.capture.provider;extra.textContent=`近 ${p.window_seconds} 秒：OCR ${p.throughput.ocr_passes_per_second}/秒 · 新文字 ${p.throughput.new_text_detections_per_second}/秒 · OCR/抽取佇列 ${p.throughput.ocr_queue_depth}/${p.throughput.extraction_queue_depth} · 最舊佇列 ${p.throughput.oldest_queue_item_age_seconds}s · CPU ${p.host.cpu_percent_since_last_sample??'—'}%（取樣間隔） · 推論 ${provider.provider} / ${provider.model} · ${provider.status}`}).catch(()=>{});
    document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>routeTo(x.dataset.route));
    document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>{state.activeId=x.dataset.open;localStorage.setItem('recall-active',state.activeId);routeTo('recall')});
    document.querySelectorAll('[data-delete-conversation]').forEach(x=>x.onclick=e=>{e.stopPropagation();const id=x.dataset.deleteConversation;confirmDelete('刪除此對話？','這會刪除該對話的原始訊息、索引與記憶。',async()=>{await api(`/conversations/${id}`,{method:'DELETE'});if(state.activeId===id)state.activeId=null;await refreshBase();await render();toast('對話已刪除')})});
    document.querySelectorAll('[data-source]').forEach(x=>x.onclick=()=>{sourceFocus=x.dataset.source;routeTo('demo-chat')});
    const sample=el('load-sample')||el('empty-sample');if(sample)sample.onclick=async()=>{sample.disabled=true;try{const r=await api('/demo/seed',{method:'POST'});state.activeId=r.conversation_id;await refreshBase();toast(r.deduplicated?'示範資料已存在':'5,000 筆資料已寫入 SQLite 並索引');await render()}catch(e){toast(e.message)}};
    if(el('open-import'))el('open-import').onclick=()=>el('import-dialog').showModal();
    if(el('conversation-select'))el('conversation-select').onchange=e=>{state.activeId=e.target.value;localStorage.setItem('recall-active',state.activeId);render()};
    document.querySelectorAll('[data-question]').forEach(x=>x.onclick=()=>{el('query').value=x.dataset.question;runQuestion()});
    if(el('ask')){el('ask').onclick=runQuestion;el('query').onkeydown=e=>{if(e.key==='Enter')runQuestion()}};
    if(el('send')){el('send').onclick=sendMessage;el('chat-input').onkeydown=e=>{if(e.key==='Enter')sendMessage()}};
    if(el('capture-start'))el('capture-start').onclick=async()=>{try{const r=await api('/system/capture/start',{method:'POST'});state.activeId=r.conversation_id;localStorage.setItem('recall-active',state.activeId);await refreshBase();toast('請在 macOS 系統選擇器選取要擷取的視窗');await render()}catch(e){toast(e.message)}};
    if(el('capture-banner-stop'))el('capture-banner-stop').onclick=async()=>{try{await api('/system/capture/stop',{method:'POST'});toast('已要求停止擷取')}catch(e){toast(e.message)}};
    for(const action of ['pause','resume','stop'])if(el(`capture-${action}`))el(`capture-${action}`).onclick=async()=>{try{await api(`/system/capture/${action}`,{method:'POST'});await render()}catch(e){toast(e.message)}};
    if(el('profiler-pause'))el('profiler-pause').onclick=async()=>{const p=await api('/system/profiler');await api('/system/profiler/pause',{method:'POST',body:JSON.stringify({paused:!p.sampling_paused})});await render()};
    if(el('profiler-reset'))el('profiler-reset').onclick=async()=>{await api('/system/profiler/reset',{method:'POST'});await render()};
    if(el('delete-active'))el('delete-active').onclick=()=>confirmDelete('刪除目前對話？','這會刪除 SQLite 中的原始訊息、FTS 索引與記憶。',async()=>{await api(`/conversations/${active().id}`,{method:'DELETE'});state.activeId=null;await refreshBase();await render();toast('對話已刪除')});
    if(el('delete-all'))el('delete-all').onclick=()=>confirmDelete('刪除全部本機資料？','所有對話、索引、記憶與匯入工作都會被移除。',async()=>{await api('/system/data',{method:'DELETE'});state.activeId=null;localStorage.removeItem('recall-active');await refreshBase();await render();toast('全部本機資料已刪除')});
  }
  function confirmDelete(title,copy,action){el('confirm-title').textContent=title;el('confirm-copy').textContent=copy;pendingConfirm=action;el('confirm-dialog').showModal()}
  function resetImport(){previewId=null;el('import-step-upload').hidden=false;el('import-preview').hidden=true;el('file-input').value=''}
  async function previewFile(file){if(file.size>8*1024*1024)return toast('檔案超過 8 MB');const content=await file.text();try{const p=await api('/imports/line/preview',{method:'POST',body:JSON.stringify({filename:file.name,content})});previewId=p.preview_id;el('import-step-upload').hidden=true;el('import-preview').hidden=false;el('import-preview').innerHTML=`<div class="callout"><strong>匯入預覽</strong><br>${p.warnings.map(esc).join('<br>')||'格式檢查完成。'}</div><div class="preview-grid"><div class="preview-item"><small>對話</small><strong>${esc(p.title)}</strong></div><div class="preview-item"><small>訊息</small><strong>${p.message_count}</strong></div><div class="preview-item"><small>參與者</small><strong>${p.participants.length}</strong></div><div class="preview-item"><small>未辨識</small><strong>${p.rejected_count}</strong></div></div><div class="preview-sample">${p.sample_messages.map(m=>`<p><strong>${esc(m.sender)}</strong> ${esc(m.content)}</p>`).join('')}</div><div class="dialog-actions"><button id="back-upload" class="btn secondary" type="button">返回</button><button id="commit-import" class="btn primary" type="button" ${p.message_count?'':'disabled'}>確認匯入並索引</button></div>`;el('back-upload').onclick=resetImport;el('commit-import').onclick=commitImport}catch(e){toast(e.message)}}
  async function commitImport(){el('commit-import').disabled=true;try{const r=await api('/imports/line/commit',{method:'POST',body:JSON.stringify({preview_id:previewId})});state.activeId=r.conversation_id;localStorage.setItem('recall-active',state.activeId);el('import-dialog').close();resetImport();await refreshBase();await routeTo('conversations');toast(`已匯入 ${r.inserted} 則訊息並抽取 ${r.memory_count} 張記憶卡`)}catch(e){toast(e.message);el('commit-import').disabled=false}}

  document.querySelectorAll('#nav [data-route],.brand').forEach(x=>x.onclick=e=>{e.preventDefault();routeTo(x.dataset.route)});
  el('file-input').onchange=e=>{const f=e.target.files[0];if(f)previewFile(f)};const dz=el('dropzone');dz.ondragover=e=>e.preventDefault();dz.ondrop=e=>{e.preventDefault();const f=e.dataTransfer.files[0];if(f)previewFile(f)};
  el('import-dialog').addEventListener('close',resetImport);el('confirm-dialog').addEventListener('close',()=>{if(el('confirm-dialog').returnValue==='default'&&pendingConfirm)pendingConfirm();pendingConfirm=null});
  refreshBase().then(()=>routeTo('conversations')).catch(e=>{el('view').innerHTML=`<div class="empty"><span class="empty-icon">!</span><h3>後端尚未啟動</h3><p>請執行 README 中的啟動指令。${esc(e.message)}</p></div>`});
  setInterval(updateCaptureBanner,1500);
})();
